"use strict";
// Self-contained report fonts. The generated HTML uses data: URIs so the
// Railway renderer never depends on container fonts or external requests.
// TeX Gyre fonts are distributed under the GUST Font License.
const fonts = {"PAGELLA_REGULAR":"","PAGELLA_BOLD":"","HEROS_REGULAR":"","HEROS_BOLD":""};
const face = (family, weight, data) =>
  `@font-face{font-family:"${family}";font-style:normal;font-weight:${weight};font-display:block;src:url(data:font/otf;base64,${data}) format("opentype")}`;
const FONT_FACE_CSS = [
  face("TeX Gyre Pagella", 400, fonts.PAGELLA_REGULAR),
  face("TeX Gyre Pagella", 700, fonts.PAGELLA_BOLD),
  face("TeX Gyre Heros", 400, fonts.HEROS_REGULAR),
  face("TeX Gyre Heros", 700, fonts.HEROS_BOLD),
].join("");
module.exports = { FONT_FACE_CSS };

